class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int maxMask = 1;
        for (int i = 0; i < numSlots; i++) maxMask *= 3;
        vector<int> dp(maxMask, 0);
        for (int x : nums) {
            for (int mask = maxMask - 1; mask >= 0; mask--) {
                int temp = mask, p = 1;
                for (int slot = 1; slot <= numSlots; slot++, p *= 3) {
                    if (temp % 3 > 0) {
                        dp[mask] = max(dp[mask], dp[mask - p] + (x & slot));
                    }
                    temp /= 3;
                }
            }
        }
        return *max_element(dp.begin(), dp.end());
    }
};

class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int maxMask = 1;
        for (int i = 0; i < numSlots; i++) maxMask *= 3;
        int[] dp = new int[maxMask];
        for (int x : nums) {
            for (int mask = maxMask - 1; mask >= 0; mask--) {
                int temp = mask, p = 1;
                for (int slot = 1; slot <= numSlots; slot++, p *= 3) {
                    if (temp % 3 > 0) {
                        dp[mask] = Math.max(dp[mask], dp[mask - p] + (x & slot));
                    }
                    temp /= 3;
                }
            }
        }
        int max = 0;
        for (int v : dp) if (v > max) max = v;
        return max;
    }
}

var maximumANDSum = function(nums, numSlots) {
    let maxMask = 1;
    for (let i = 0; i < numSlots; i++) maxMask *= 3;
    const dp = new Int32Array(maxMask);
    for (const x of nums) {
        for (let mask = maxMask - 1; mask >= 0; mask--) {
            let temp = mask, p = 1;
            for (let slot = 1; slot <= numSlots; slot++, p *= 3) {
                if (temp % 3 > 0) {
                    const cand = dp[mask - p] + (x & slot);
                    if (cand > dp[mask]) dp[mask] = cand;
                }
                temp = Math.floor(temp / 3);
            }
        }
    }
    let max = 0;
    for (let i = 0; i < maxMask; i++) if (dp[i] > max) max = dp[i];
    return max;
};
